                "hierarchy",
                "charge_curve",
                "prices",
                "calendars",
                "ev",
                "tariff_list",
                "reset_data",
                "finish",
            ],
        )

    async def async_step_finish(self, user_input: dict[str, Any] | None = None) -> ConfigFlowResult:
        self._ensure_loaded()
        return self.async_create_entry(title="", data=self._data)

